exports.init = (params, rng) => {
  const supply = params.supplyLevel ?? 1;
  const demand = params.demandLevel ?? 1;
  const base = params.baselinePrice ?? 10;
  const buyerCount = Math.max(1, Math.round(80 * demand));
  const sellerCount = Math.max(1, Math.round(80 * supply));
  const buyers = [];
  for (let i = 0; i < buyerCount; i++) {
    const frac = (i + 0.5) / buyerCount;
    const wtp = (base - 10) + 20 * frac;
    buyers.push({
      id: `b${i}`,
      x: 0.22 + rng.range(-0.08, 0.08),
      y: 0.25 + rng.range(-0.18, 0.18) + (i % 7) * 0.02,
      wtp,
      trading: false
    });
  }
  const sellers = [];
  for (let i = 0; i < sellerCount; i++) {
    const frac = (i + 0.5) / sellerCount;
    const cost = (base - 10) + 20 * frac;
    sellers.push({
      id: `s${i}`,
      x: 0.78 + rng.range(-0.08, 0.08),
      y: 0.25 + rng.range(-0.18, 0.18) + (i % 7) * 0.02,
      cost,
      trading: false
    });
  }
  return {
    price: base,
    quantity_traded: 0,
    buyers,
    sellers,
    tick: 0
  };
};

exports.step = (state, params, rng) => {
  let price = state.price;
  let willingBuyers = 0;
  for (const b of state.buyers) if (b.wtp >= price) willingBuyers++;
  let willingSellers = 0;
  for (const s of state.sellers) if (s.cost <= price) willingSellers++;
  const excess = willingBuyers - willingSellers;
  const k = 0.06;
  price = price + k * excess;
  if (price < 1) price = 1;
  if (price > 30) price = 30;
  let willingBuyers2 = 0;
  for (const b of state.buyers) if (b.wtp >= price) willingBuyers2++;
  let willingSellers2 = 0;
  for (const s of state.sellers) if (s.cost <= price) willingSellers2++;
  const quantity = Math.min(willingBuyers2, willingSellers2);
  const buyersSorted = [...state.buyers].sort((a,b) => b.wtp - a.wtp);
  const sellersSorted = [...state.sellers].sort((a,b) => a.cost - b.cost);
  const willingBuyersSorted = buyersSorted.filter(b => b.wtp >= price);
  const willingSellersSorted = sellersSorted.filter(s => s.cost <= price);
  const tradingBuyerIds = new Set(willingBuyersSorted.slice(0, quantity).map(b => b.id));
  const tradingSellerIds = new Set(willingSellersSorted.slice(0, quantity).map(s => s.id));
  const newBuyers = state.buyers.map(b => ({
    ...b,
    trading: tradingBuyerIds.has(b.id),
    x: Math.max(0.05, Math.min(0.45, b.x + rng.range(-0.005, 0.005))),
    y: Math.max(0.1, Math.min(0.9, b.y + rng.range(-0.005, 0.005)))
  }));
  const newSellers = state.sellers.map(s => ({
    ...s,
    trading: tradingSellerIds.has(s.id),
    x: Math.max(0.55, Math.min(0.95, s.x + rng.range(-0.005, 0.005))),
    y: Math.max(0.1, Math.min(0.9, s.y + rng.range(-0.005, 0.005)))
  }));
  return {
    price,
    quantity_traded: quantity,
    buyers: newBuyers,
    sellers: newSellers,
    tick: state.tick + 1
  };
};

exports.observe = (state, params) => {
  return {
    market_price: Math.round(state.price * 10) / 10,
    quantity_traded: state.quantity_traded
  };
};

exports.view = (state, params) => {
  const agents = [];
  for (const b of state.buyers) {
    agents.push({
      id: b.id,
      x: b.x,
      y: b.y,
      tint: b.trading ? 0.85 : 0.15,
      sprite: "buyer",
      bubble: b.trading ? null : (state.price > b.wtp + 3 ? "Too dear!" : null)
    });
  }
  for (const s of state.sellers) {
    agents.push({
      id: s.id,
      x: s.x,
      y: s.y,
      tint: s.trading ? 0.85 : 0.32,
      sprite: "seller",
      bubble: s.trading ? "Sold!" : null
    });
  }
  return { kind: "population", agents };
};
